package Patternsinjava;

public class Pattern2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//rectangle

		int c=2;
		int r=8;
		
		for(int i=0;i<=c;i++)
		{
			for(int j=0;j<=r;j++)
			{
				System.out.print("*");
			}
			System.out.println();
		}
	}

}
